from html.parser import HTMLParser

class HTMLValidator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.tags = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in ['br','hr','img','input','meta','link','canvas']:
            self.tags.append(tag)
    def handle_endtag(self, tag):
        if tag not in ['br','hr','img','input','meta','link','canvas']:
            if self.tags and self.tags[-1] == tag:
                self.tags.pop()
            else:
                self.errors.append(f'Unexpected closing tag: {tag}')

with open('/app/output/final_report.html', 'r') as f:
    content = f.read()

validator = HTMLValidator()
validator.feed(content)

print('File size:', len(content), 'bytes')
print('Unclosed tags:', validator.tags)
print('Errors:', validator.errors)
print('Contains Chart.js CDN:', 'chart.js' in content)
print('Contains all sections:', all(s in content for s in ['publication-volume-trends','geographic-landscape','topic-and-mesh-analysis','open-access-patterns','research-type-collaboration','key-takeaways']))
"
